using System;
using System.IO;
using System.Linq;
using System.Text;
namespace DoomSNESed {
    public static class AudioTests {
        static void Check(bool value,string message){Bin.Require(value,"Audio 0.5: "+message);}
        static void Be32(BinaryWriter writer,int value){writer.Write((byte)(value>>24));writer.Write((byte)(value>>16));writer.Write((byte)(value>>8));writer.Write((byte)value);}
        static byte[] Midi(byte[] events=null){using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){writer.Write(Encoding.ASCII.GetBytes("MThd"));Be32(writer,6);writer.Write(new byte[]{0,0,0,1,1,0xe0});var track=events??new byte[]{0,0xc0,30,0,0xff,81,3,7,0xa1,0x20,0,0x90,60,100,0x81,0x70,64,100,0x81,0x70,60,0,0x81,0x70,64,0,0,0xff,47,0};writer.Write(Encoding.ASCII.GetBytes("MTrk"));Be32(writer,track.Length);writer.Write(track);return stream.ToArray();}}
        public static void Run(string romPath,string output){string resources=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data");string audioDir=Path.Combine(output,"audio-05");Directory.CreateDirectory(audioDir);var rom=new Rom(romPath,resources);
            using(var form=new ConverterForm()){var field=typeof(ConverterForm).GetField("tabs",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var tabs=(System.Windows.Forms.TabControl)field.GetValue(form);Check(tabs.TabPages.Cast<System.Windows.Forms.TabPage>().Select(p=>p.Text).SequenceEqual(new[]{"Maps","Optimization","Textures","Skies","Sprites","Graphics","Music","Sounds","Ending Text","Credits","Copyright","Report"}),"each converter section has its own accessible tab");}
            byte[] input=Enumerable.Range(0,642).Select(i=>(byte)(i*37)).ToArray(),packed=NativeCompression.EncodeLiterals(input);Check(NativeCompression.Decode(packed,0).SequenceEqual(input),"native RLC encoding initializes the RAM turbo table");
            var slots=AudioRom.Sounds(rom.Bytes,resources);Check(slots.Count==36&&slots.Single(s=>s.Wave==10).Effects.Length==3,"all resident and turbo sample slots / distance aliases identified");foreach(var slot in slots)Check(WavImport.Decode(AudioRom.Sample(rom.Bytes,slot)).Length>0,"retail BRR sample decodes "+slot.Wave);
            string midi=Path.Combine(audioDir,"fixture.mid"),mus=Path.Combine(audioDir,"fixture.mus");File.WriteAllBytes(midi,Midi());var notes=MusicImport.Read(midi);Check(notes.Notes.Count==2&&Math.Abs(notes.Notes[0].End-.5)<.0001&&Math.Abs(notes.Seconds-.75)<.0001,"MIDI running status, chords and PPQN tempo");byte[] musBytes=new byte[24];Buffer.BlockCopy(Encoding.ASCII.GetBytes("MUS\x1a"),0,musBytes,0,4);Bin.W16(musBytes,4,8);Bin.W16(musBytes,6,16);Bin.W16(musBytes,8,1);Buffer.BlockCopy(new byte[]{0x90,188,100,70,0x80,60,70,0x60},0,musBytes,16,8);File.WriteAllBytes(mus,musBytes);var musNotes=MusicImport.Read(mus);Check(musNotes.Notes.Count==1&&Math.Abs(musNotes.Seconds-.5)<.0001,"Doom MUS note velocity and 140 Hz timing");var music=MusicImport.Convert(notes,"E1M1",6,0,true);AudioBuild.ValidateMusic(music);Check(music.Voices==2,"overlapping notes receive independent native voices");var single=MusicImport.Convert(notes,"E1M1",1,0,false);Check(single.Voices==1&&single.Report.Contains("1 overlapping"),"voice concession is reported");
            var pcm=new short[2205];for(int i=0;i<pcm.Length;i++)pcm[i]=(short)(Math.Sin(i*Math.PI*2*440/11025)*22000);byte[] brr=WavImport.Encode(pcm,false);short[] decoded=WavImport.Decode(brr);double error=0,signal=0;for(int i=0;i<pcm.Length;i++){double delta=pcm[i]-decoded[i];error+=delta*delta;signal+=(double)pcm[i]*pcm[i];}Check(10*Math.Log10(signal/error)>25,"adaptive BRR preserves a test tone with >25 dB SNR");string wave=Path.Combine(audioDir,"fixture.wav");File.WriteAllBytes(wave,WavImport.WaveFile(pcm,11025));var pistol=WavImport.Convert(wave,slots.Single(s=>s.Wave==10),true,true,false,false);var door=WavImport.Convert(wave,slots.Single(s=>s.Wave==6),true,true,false,false);bool refused=false;try{WavImport.Convert(wave,slots.Single(s=>s.Wave==4),false,false,false,false);}catch(InvalidDataException){refused=true;}Check(refused,"oversized WAV rejected unless tail trimming is explicit");var fitted=WavImport.Convert(wave,slots.Single(s=>s.Wave==4),false,false,true,false);Check(fitted.Data.Length<=slots.Single(s=>s.Wave==4).Bytes&&fitted.Report.Contains("truncated"),"explicit WAV fit is bounded and reported");
            string sustained=Path.Combine(audioDir,"sustain-tempo.mid");File.WriteAllBytes(sustained,Midi(new byte[]{0,0xff,81,3,7,0xa1,0x20,0,0xb0,64,127,0,0x90,60,100,0x83,0x60,0x80,60,0,0,0xff,81,3,3,0xd0,0x90,0x83,0x60,0xb0,64,0,0,0xff,47,0}));var pedal=MusicImport.Read(sustained);Check(pedal.Notes.Count==1&&Math.Abs(pedal.Notes[0].End-.75)<.0001,"sustain release respects a mid-score tempo change");
            string floating=Path.Combine(audioDir,"stereo-float.wav");using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){int frames=4410;writer.Write(Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+frames*8);writer.Write(Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)3);writer.Write((short)2);writer.Write(44100);writer.Write(44100*8);writer.Write((short)8);writer.Write((short)32);writer.Write(Encoding.ASCII.GetBytes("data"));writer.Write(frames*8);for(int i=0;i<frames;i++){float sample=(float)Math.Sin(i*2*Math.PI*440/44100);writer.Write(sample*.75f);writer.Write(sample*.25f);}File.WriteAllBytes(floating,stream.ToArray());}var stereo=WavImport.Convert(floating,slots.Single(s=>s.Wave==10),false,false,false,false);Check(WavImport.Decode(stereo.Data).Length==1104,"44.1 kHz stereo float WAV mixes and resamples to native mono");
            rom.LoadProject(Path.Combine(output,"native-campaign.sned"));rom.Project.Audio.Music.Add(music);rom.Project.Audio.Sounds.Add(pistol);rom.Project.Audio.Sounds.Add(door);byte[] image=rom.Compile();Check(Bin.U16(image,AudioRom.SongTable)==0x1502,"custom music assigned to the actual starting map");Check(rom.Budget.Music>music.Sequence.Length&&rom.Budget.Sounds==pistol.Data.Length+door.Data.Length+2,"allocation meter includes audio table overhead and resident uploads");string project=Path.Combine(audioDir,"native-audio.sned");rom.SaveProject(project);rom.SavePatch(Path.Combine(audioDir,"native-audio.dse"),image);Bin.Atomic(Path.Combine(audioDir,"native-audio.sfc"),image);var reopened=new Rom(romPath,resources);reopened.LoadProject(project);Check(reopened.Compile().SequenceEqual(image),"MIDI/WAV replacements persist and recompile exactly");Check(Encoding.ASCII.GetString(File.ReadAllBytes(Path.Combine(audioDir,"native-audio.dse")),0,8)=="DSEAUD4\0","native audio patch has dedicated validated profile");
            // A MUS import produces its own native campaign, rather than a host-side track.
            reopened.Project.Audio.Music[0]=MusicImport.Convert(musNotes,"E1M1",6,0,true);byte[] musImage=reopened.Compile();reopened.SavePatch(Path.Combine(audioDir,"native-mus.dse"),musImage);Bin.Atomic(Path.Combine(audioDir,"native-mus.sfc"),musImage);
            // A larger first map may be stored outside E1M1; its song must follow the alias.
            var alias=new Rom(romPath,resources);alias.LoadProject(project);Map selected=alias.Project.Maps.First(m=>m.Slot==alias.Project.CampaignSlots[0]);selected.Slot=1;alias.Project.Maps.RemoveAll(m=>m!=selected&&m.Slot==1);alias.Project.CampaignSlots=new[]{1};byte[] aliased=alias.Compile();Check(Bin.U16(aliased,AudioRom.SongTable)==Bin.U16(aliased,AudioRom.SongTable+2)&&Bin.U16(aliased,AudioRom.SongTable)==0x1502,"first-map storage alias also carries its custom music");
            AudioAdvancedTests.Run(romPath,output);Check(Bin.Hex(Bin.Hash(rom.Bytes))==Rom.Identity,"audio compilation preserves source ROM");File.WriteAllText(Path.Combine(audioDir,"results.txt"),"PASS: MIDI running status/chords/tempo; MUS timing; voice concession reports; native RLC and all 36 retail BRR decoders; adaptive BRR tone quality; explicit WAV fit and rejection; resident and streamed sound replacement; native music assignment; ROM/SPC allocation accounting; editable project round-trip; base ROM unchanged.\r\n"+music.Report+"\r\n"+pistol.Report+"\r\nROM maps="+rom.Budget.Maps+", graphics="+rom.Budget.Graphics+", music/tables="+rom.Budget.Music+", sound="+rom.Budget.Sounds+", total capacity="+rom.Budget.Capacity+"\r\n");
        }
    }
}

